<template><div class="page"><div class="head"><div><span>PHM SECURITY / ACCESS CONTROL</span><h2>用户与权限</h2><p>按角色控制数据查看、结构维护、仿真提交和结果发布权限。</p></div><el-button @click="load" :loading="loading">刷新</el-button></div><el-card shadow="never" class="profile"><b>当前会话</b><span v-if="profile">{{profile.username}} · {{roleLabel(profile.role)}}</span><el-tag v-if="profile" type="success">{{profile.permissions.length}} 项权限</el-tag><el-alert v-else type="warning" title="未登录或会话已过期，请先登录" :closable="false"/></el-card><el-card shadow="never"><template #header><b>角色权限目录</b></template><el-table :data="roles" stripe><el-table-column prop="key" label="角色" width="130"><template #default="s">{{roleLabel(s.row.key)}}</template></el-table-column><el-table-column label="可执行权限"><template #default="s"><el-tag v-for="x in s.row.permissions" :key="x" size="small" effect="plain">{{permissionLabel(x)}}</el-tag></template></el-table-column></el-table></el-card><el-card shadow="never" class="notice"><b>安全说明</b><p>分析数据默认按登录会话访问；管理员负责角色分配，工程师可维护结构和仿真任务，操作员可提交分析，查看者仅可浏览结果。</p></el-card></div></template>
<script setup>import{ref,onMounted}from'vue';import api from'../api';import{ElMessage}from'element-plus';const profile=ref(null),roles=ref([]),loading=ref(false);const labels={admin:'管理员',engineer:'工程师',operator:'操作员',viewer:'查看者',view:'查看数据',manage_users:'管理用户',manage_structure:'维护结构',submit_simulation:'提交仿真',run_analysis:'执行分析',publish:'发布结果'};const roleLabel=x=>labels[x]||x;const permissionLabel=x=>labels[x]||x;const load=async()=>{loading.value=true;try{profile.value=(await api.get('/permissions/profile/')).data;roles.value=(await api.get('/permissions/roles/')).data.roles}catch(e){profile.value=null;ElMessage.warning('请登录后查看权限信息')}finally{loading.value=false}};onMounted(load)</script>
<style scoped>.head{display:flex;justify-content:space-between;align-items:end;margin-bottom:18px}.head span{font-size:11px;color:#287de6;font-weight:700;letter-spacing:1px}.head h2{margin:7px 0}.head p{margin:0;color:#8391a5}.el-card{border-radius:11px;margin-bottom:16px}.profile{display:flex;align-items:center;gap:18px}.profile span{color:#50647b}.el-tag{margin:3px}.notice p{color:#65768c}</style>
